output_text:
[
  {
    "id": "no_cart_in_single_file_aisles",
    "text": "Shopping carts are forbidden in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "retrieve_parked_cart",
    "text": "Whenever a customer parks or releases a cart, they are obliged to retrieve a cart before finishing the trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartDropped": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartRetrieved": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartDropped",
      "discharge": "cartRetrieved"
    }
  },
  {
    "id": "cartless_only_toward_single_file_or_cart",
    "text": "Outside single-file aisles, a cartless customer may not wander around; they may only move north into the aisle or interact to recover the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "cartlessOpenArea": {
          "and": [
            {
              "not": "hasCart"
            },
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartlessOpenArea",
          "MOVE",
          {
            "not": "N"
          }
        ]
      }
    }
  },
  {
    "id": "open_shelf_interactions_need_cart",
    "text": "Shelf interactions in ordinary open aisles require the customer to have a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openShelfAccess": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "openShelfAccess",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "enter_single_file_without_cart",
    "text": "A customer must not enter a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "single_file_entry_requires_shopping",
    "text": "After entering a single-file shelf aisle without a cart, the customer is obliged to perform a shelf interaction there before leaving the aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileNoCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileAisle"
        },
        "singleFileShelfInteraction": {
          "pre": {
            "and": [
              "singleFileAisle",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileNoCart",
      "discharge": "singleFileShelfInteraction"
    }
  },
  {
    "id": "cart_parking_only_at_aisle_mouths",
    "text": "Carts may only be put down at designated wide aisle-mouth staging cells before entering a narrow shelf aisle.",
    "abstraction": {
      "state_properties": {
        "aisleMouthCartPark": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "cartDroppedAwayFromMouth": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT",
              {
                "not": "aisleMouthCartPark"
              }
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartDroppedAwayFromMouth"
    }
  },
  {
    "id": "return_to_cart_after_single_file_pickup",
    "text": "After taking an item from a single-file shelf aisle, the customer is obliged to return and retrieve the cart before continuing the trip.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "singleFileShelfInteraction": {
          "pre": {
            "and": [
              "singleFileAisle",
              "INTERACT"
            ]
          },
          "post": null
        },
        "cartRetrieved": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "singleFileShelfInteraction",
      "discharge": "cartRetrieved"
    }
  }
]
